  const hero = document.querySelector<HTMLElement>('.hero')
  const card = document.querySelector<HTMLElement>('[data-console]')
  if (hero && card) mountNetwork(hero, card)

  const eyebrow = document.querySelector<HTMLElement>('[data-typed]')
  if (eyebrow && !prefersReducedMotion()) {
    const text = eyebrow.textContent ?? ''
    eyebrow.textContent = ''

    // rAF, not an interval: the 700ms wait is an offset on the elapsed time, so the
    // typing stays in step with the boot transitions instead of drifting past them.
    let start: number | undefined
    const step = (now: number) => {
      start ??= now
      const n = typedLength(now - start - 700, 28, text.length)
      eyebrow.textContent = text.slice(0, n)
      if (n < text.length) requestAnimationFrame(step)
    }
    requestAnimationFrame(step)
  }
