const D = () => K.duration.v
const at = (i) => PHASES[i][0] * D()
const to = (i) => PHASES[i][1] * D()

function setBoot(el, on, dy = 14) {
  el.style.opacity = on
  el.style.transform = `translateY(${(1 - on) * dy}px)`
  el.style.filter = `blur(${(1 - on) * 8}px)`
}

const GLYPHS = '<>/_-=+*#%&{}[]|\\01'
function scrambled(text, p) {
  const n = Math.floor(p * p * text.length)
  let out = ''
  for (let i = 0; i < text.length; i++) {
    if (text[i] === ' ') out += ' '
    else out += i < n ? text[i] : GLYPHS[(i * 7 + Math.floor(p * 40)) % GLYPHS.length]
  }
  return out
}

function frame(t) {
  sceneCtx.clearRect(0, 0, W, H)
  logoCtx.clearRect(0, 0, W, H)

  const navBox = navSlot.getBoundingClientRect()
  const stageBox = stage.getBoundingClientRect()
  const navX = navBox.left - stageBox.left + navBox.width / 2
  const navY = navBox.top - stageBox.top + navBox.height / 2

  const heroX = W * 0.5
  const heroY = H * 0.43

  // --- logo transform across the timeline ---
  const pSeed = norm(t, at(0), to(0))
  const pExp = norm(t, at(1), to(1))
  const pDock = norm(t, at(2), to(2))

  const expand = lerp(0.08, 1, outBack(clamp(pExp)))
  const dock = inOut(pDock)
  const cx = lerp(heroX, navX, dock)
  const cy = lerp(heroY, navY, dock)
  const big = Math.min(W, H) * 0.19 * K.scale.v
  const small = navBox.width * 0.3
  const s = lerp(big * lerp(0.25, 1, outCubic(clamp(pExp))), small, dock)

  const wry = t * 0.00028 * K.globalSpin.v + (1 - clamp(pExp)) * 2.4
  const wrx = K.tilt.v + Math.sin(t * 0.0004) * 0.05

  const settle = outCubic(clamp((pExp - 0.25) / 0.75))
  ctx = logoCtx
  drawLogo({ cx, cy, s, f: 900, wrx, wry, expand, t, settle, alpha: lerp(0.35, 1, clamp(pSeed * 2)) })

  ctx = sceneCtx

  // --- energy -> node network ---
  const pEnergy = norm(t, at(3), to(3))
  const pCon = norm(t, at(4), to(4))
  if (pEnergy > 0) {
    const n = Math.round(K.nodes.v)
    const rx = W * 0.26
    const ry = H * 0.3
    const rz = Math.min(W, H) * 0.3
    const ncx = W * 0.72
    const ncy = H * 0.55
    const pts = []
    for (let i = 0; i < n; i++) {
      const nd = NODES[i]
      const th = nd.th + t * nd.spd
      const p3 = rot3(
        {
          x: Math.sin(nd.ph) * Math.cos(th) * rx * nd.r,
          y: Math.cos(nd.ph) * ry * nd.r,
          z: Math.sin(nd.ph) * Math.sin(th) * rz * nd.r,
        },
        0.1,
        0,
        0,
      )
      const f = 0.9 * Math.max(W, H)
      const sc = f / (f + p3.z)
      const tx = ncx + p3.x * sc
      const ty = ncy + p3.y * sc
      const e = outCubic(clamp((pEnergy - nd.d * 0.5) * 2))
