      pts.push({ x: mx, y: my, sc, a: e * lerp(1, 0.75, pCon) })
    }
    ctx.lineWidth = 1
    for (let i = 0; i < pts.length; i++) {
      for (let j = i + 1; j < pts.length; j++) {
        const dx = pts[i].x - pts[j].x
        const dy = pts[i].y - pts[j].y
        const d = Math.hypot(dx, dy)
        if (d < 110) {
          ctx.strokeStyle = `rgba(${AC()},${(1 - d / 110) * 0.2 * Math.min(pts[i].a, pts[j].a)})`
          ctx.beginPath()
          ctx.moveTo(pts[i].x, pts[i].y)
          ctx.lineTo(pts[j].x, pts[j].y)
          ctx.stroke()
        }
      }
    }
    for (const p of pts) {
      ctx.fillStyle = `rgba(${AC()},${0.75 * p.a})`
      ctx.beginPath()
