  const dock = inOut(pDock)
  const cx = lerp(heroX, navX, dock)
  const cy = lerp(heroY, navY, dock)
  const big = Math.min(W, H) * 0.19 * K.scale.v
  const small = navBox.width * 0.3
  const s = lerp(big * lerp(0.25, 1, outCubic(clamp(pExp))), small, dock)

  const wry = t * 0.00028 * K.globalSpin.v + (1 - clamp(pExp)) * 2.4
  const wrx = K.tilt.v + Math.sin(t * 0.0004) * 0.05

  const settle = outCubic(clamp((pExp - 0.25) / 0.75))
  ctx = logoCtx
  drawLogo({ cx, cy, s, f: 900, wrx, wry, expand, t, settle, alpha: lerp(0.35, 1, clamp(pSeed * 2)) })

  ctx = sceneCtx

  // --- energy -> node network ---
  const pEnergy = norm(t, at(3), to(3))
  const pCon = norm(t, at(4), to(4))
  if (pEnergy > 0) {
    const n = Math.round(K.nodes.v)
    const rx = W * 0.26
    const ry = H * 0.3
    const rz = Math.min(W, H) * 0.3
    const ncx = W * 0.72
    const ncy = H * 0.55
    const pts = []
    for (let i = 0; i < n; i++) {
      const nd = NODES[i]
      const th = nd.th + t * nd.spd
      const p3 = rot3(
        {
          x: Math.sin(nd.ph) * Math.cos(th) * rx * nd.r,
          y: Math.cos(nd.ph) * ry * nd.r,
          z: Math.sin(nd.ph) * Math.sin(th) * rz * nd.r,
        },
        0.1,
        0,
        0,
      )
      const f = 0.9 * Math.max(W, H)
      const sc = f / (f + p3.z)
      const tx = ncx + p3.x * sc
      const ty = ncy + p3.y * sc
      const e = outCubic(clamp((pEnergy - nd.d * 0.5) * 2))
      // A slight arc so the particles fall out of the logo instead of sliding.
      const mx = lerp(cx, tx, e)
      const my = lerp(cy, ty, e) - Math.sin(e * Math.PI) * H * 0.12
      pts.push({ x: mx, y: my, sc, a: e * lerp(1, 0.75, pCon) })
    }
    ctx.lineWidth = 1
    for (let i = 0; i < pts.length; i++) {
      for (let j = i + 1; j < pts.length; j++) {
        const dx = pts[i].x - pts[j].x
        const dy = pts[i].y - pts[j].y
        const d = Math.hypot(dx, dy)
        if (d < 110) {
          ctx.strokeStyle = `rgba(${AC()},${(1 - d / 110) * 0.2 * Math.min(pts[i].a, pts[j].a)})`
          ctx.beginPath()
          ctx.moveTo(pts[i].x, pts[i].y)
          ctx.lineTo(pts[j].x, pts[j].y)
          ctx.stroke()
        }
      }
    }
    for (const p of pts) {
      ctx.fillStyle = `rgba(${AC()},${0.75 * p.a})`
      ctx.beginPath()
      ctx.arc(p.x, p.y, 1.5 * p.sc, 0, 7)
      ctx.fill()
    }
  }

  // --- DOM: nav name, console, boot cascade ---
  // MOTION_SPEC 1: the brand resolves left to right with quadratic easing. Same
  // function the nav already runs on load, only its trigger moves here.
  const pName = norm(t, at(2) + (to(2) - at(2)) * 0.62, to(2) + D() * 0.16)
  navName.style.opacity = pName > 0 ? 1 : 0
  navName.textContent = scrambled('MARCOS ARRIETA', pName)

  const conP = outCubic(norm(t, at(4), to(4)))
  consoleEl.style.opacity = conP
  consoleEl.style.transform = `translateY(${(1 - conP) * 24}px) scale(${lerp(0.96, 1, conP)})`
  consoleEl.style.filter = `blur(${(1 - conP) * 10}px)`
  const sweep = norm(t, at(4) + (to(4) - at(4)) * 0.35, to(4) + D() * 0.04)
  consoleEl.style.setProperty('--sweep', `${sweep * 100}%`)
  consoleEl.style.setProperty('--sweep-a', sweep > 0 && sweep < 1 ? 1 : 0)

  const c0 = at(5)
  const stepMs = D() * 0.038
  document.querySelectorAll('[data-boot]').forEach((el) => {
    const n = +el.dataset.boot
    setBoot(el, outCubic(norm(t, c0 + n * stepMs, c0 + n * stepMs + D() * 0.09)))
  })
  const typedN = Math.floor(norm(t, c0, c0 + D() * 0.11) * TYPED_TEXT.length)
  typed.textContent = TYPED_TEXT.slice(0, typedN)

  // Phases overlap, so the label is the last one to have started, not the only match.
  const ph = [...PHASES].reverse().find(([a]) => t >= a * D()) || PHASES[0]
  phaseTag.textContent = ph[2]
  ;[...rows.children].forEach((tr, i) => (tr.dataset.active = String(PHASES[i] === ph)))
}

// ---------- transport ----------
const scrub = document.getElementById('scrub')
const tLabel = document.getElementById('tLabel')
const play = document.getElementById('play')
const loopBtn = document.getElementById('loop')
let T = 0
let playing = false
let looping = true
let last = 0

